ALTER TABLE public.explorations ADD COLUMN IF NOT EXISTS technical_content text NOT NULL DEFAULT '';
ALTER TABLE public.explorations ADD COLUMN IF NOT EXISTS product_price_inr numeric;
ALTER TABLE public.explorations ADD COLUMN IF NOT EXISTS paid_parts boolean NOT NULL DEFAULT false;
CREATE TABLE public.exploration_likes (exploration_id uuid NOT NULL REFERENCES public.explorations(id) ON DELETE CASCADE, user_id uuid NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY (exploration_id,user_id));
GRANT SELECT, INSERT, DELETE ON public.exploration_likes TO authenticated;
GRANT ALL ON public.exploration_likes TO service_role;
ALTER TABLE public.exploration_likes ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Own exploration likes" ON public.exploration_likes FOR SELECT TO authenticated USING (user_id=auth.uid());
CREATE POLICY "Like visible exploration" ON public.exploration_likes FOR INSERT TO authenticated WITH CHECK (user_id=auth.uid() AND EXISTS (SELECT 1 FROM public.explorations e WHERE e.id=exploration_id AND e.is_visible));
CREATE POLICY "Unlike own exploration" ON public.exploration_likes FOR DELETE TO authenticated USING (user_id=auth.uid());
CREATE TABLE public.exploration_views (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), exploration_id uuid NOT NULL REFERENCES public.explorations(id) ON DELETE CASCADE, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.exploration_views TO authenticated;
GRANT ALL ON public.exploration_views TO service_role;
ALTER TABLE public.exploration_views ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Admin view analytics" ON public.exploration_views FOR SELECT TO authenticated USING (public.has_role(auth.uid(),'admin'));
CREATE FUNCTION public.record_exploration_view(p_id uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF EXISTS (SELECT 1 FROM public.explorations WHERE id=p_id AND is_visible) THEN INSERT INTO public.exploration_views(exploration_id) VALUES(p_id); END IF; END; $$;
REVOKE ALL ON FUNCTION public.record_exploration_view(uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.record_exploration_view(uuid) TO anon,authenticated;
CREATE FUNCTION public.exploration_like_count(p_id uuid) RETURNS bigint LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT count(*) FROM public.exploration_likes l WHERE l.exploration_id=p_id AND EXISTS (SELECT 1 FROM public.explorations e WHERE e.id=p_id AND e.is_visible); $$;
REVOKE ALL ON FUNCTION public.exploration_like_count(uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.exploration_like_count(uuid) TO anon,authenticated;
ALTER PUBLICATION supabase_realtime ADD TABLE public.exploration_likes;